    Directory.GetFiles(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget/packages/microsoft.agents.ai"), "Microsoft.Agents.AI.dll", SearchOption.AllDirectories).OrderByDescending(x => x).FirstOrDefault(),
    Directory.GetFiles(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget/packages/microsoft.agents.ai.abstractions"), "Microsoft.Agents.AI.Abstractions.dll", SearchOption.AllDirectories).OrderByDescending(x => x).FirstOrDefault()
};

foreach (var p in paths.Where(p => p != null))
{
    try
    {
        Console.WriteLine($"\n{'='*70}");
        Console.WriteLine($"=== {Path.GetFileName(p)} ===");
        Console.WriteLine($"From: {p}");
        Console.WriteLine($"{'='*70}\n");

        var asm = Assembly.LoadFrom(p!);

        foreach (var t in asm.GetExportedTypes().OrderBy(t => t.FullName))
        {
            var kind = t.IsInterface ? "interface" : t.IsAbstract ? "abstract" : t.IsEnum ? "enum" : "class";
            Console.WriteLine($"[{kind}] {t.FullName}");

            // List properties
            var props = t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
            foreach (var prop in props)
            {
                Console.WriteLine($"  └─ {prop.PropertyType.Name} {prop.Name} {{ get; set; }}");
            }

            // List methods (skip special names like get_/set_)
            var methods = t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
                .Where(m => !m.IsSpecialName && m.DeclaringType == t)
                .OrderBy(m => m.Name);

            foreach (var m in methods)
            {
                var returnType = m.ReturnType.Name;
                var parms = string.Join(", ", m.GetParameters().Select(p2 => $"{p2.ParameterType.Name} {p2.Name}"));
                Console.WriteLine($"  └─ {returnType} {m.Name}({parms})");
            }

            // List nested types
            var nested = t.GetNestedTypes(BindingFlags.Public);
            foreach (var nt in nested)
            {
                Console.WriteLine($"  └─ nested: {nt.Name}");
            }

            Console.WriteLine();
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"ERROR loading {p}: {ex.Message}");
    }
}
EOF

