using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Shared state for the note-taking tool ---
var notebook = new ResearchNotebook();

// --- Build the chat client through the MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools via AIFunctionFactory ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
            WebSearchAsync(query),
        "web_search",
        "Searches the web for a given query and returns a summary of the top results. " +
        "Use this to find information about a topic."),

    AIFunctionFactory.Create(
        ([Description("Title or label for this note")] string title,
         [Description("The content to save")] string content) =>
            notebook.SaveNote(title, content),
        "save_note",
        "Saves a research note with a title and content. " +
        "Use this to record important findings during research."),

    AIFunctionFactory.Create(
        () => notebook.GetAllNotes(),
        "get_notes",
        "Retrieves all saved research notes. " +
        "Use this to review what has been recorded so far."),
};

// --- Configure the agent ---
var agentOptions = new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Instructions = """
        You are a research agent. When the user gives you a topic:
        1. Search the web 2-3 times with different queries to gather information.
        2. Save the most important findings as notes using the save_note tool.
        3. After researching, retrieve your notes and produce a well-structured
           summary with key points, organized by theme.
        Be thorough but concise. Cite the sources you found.
        """,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = tools,
    },
};

var agent = new ChatClientAgent(chatClient, agentOptions);

// --- Main loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (GPT-4o-mini)   ║");
Console.WriteLine("║  Type a topic to research, or 'quit'.    ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;
    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    Console.WriteLine($"\n🔍 Researching: {topic}\n");

    try
    {
        var session = await agent.CreateSessionAsync();
        var runOptions = new ChatClientAgentRunOptions();

        await foreach (var update in agent.RunStreamingAsync(
            topic, session, runOptions, CancellationToken.None))
        {
            Console.Write(update.Text);
        }

        Console.WriteLine("\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}\n");
    }
}

Console.WriteLine("Goodbye!");
return;

// --- Web search implementation ---
static async Task<string> WebSearchAsync(string query)
{
    Console.WriteLine($"  🌐 Searching: \"{query}\"");

    try
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
        http.Timeout = TimeSpan.FromSeconds(10);

        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

        var html = await http.GetStringAsync(url);

        // Extract text from the HTML results
        var text = StripHtml(html);

        // Truncate to a reasonable size for the LLM context
        const int maxChars = 3000;
        if (text.Length > maxChars)
            text = text[..maxChars] + "\n[...truncated]";

        return string.IsNullOrWhiteSpace(text)
            ? "No results found."
            : $"Search results for \"{query}\":\n{text}";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

static string StripHtml(string html)
{
    // Remove script/style blocks, then tags, then collapse whitespace
    var text = Regex.Replace(html, @"<(script|style)[^>]*>.*?</\1>", "", RegexOptions.Singleline);
    text = Regex.Replace(text, @"<[^>]+>", " ");
    text = WebUtility.HtmlDecode(text);
    text = Regex.Replace(text, @"\s+", " ").Trim();
    return text;
}

// --- Notebook ---
sealed class ResearchNotebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public string SaveNote(string title, string content)
    {
        _notes.Add((title, content));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note \"{title}\" saved successfully. You now have {_notes.Count} note(s).";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"--- Note {i + 1}: {_notes[i].Title} ---");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

