    Console.WriteLine($"  🌐 Searching: \"{query}\"");

    try
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
        http.Timeout = TimeSpan.FromSeconds(10);

        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

        var html = await http.GetStringAsync(url);

        // Extract text from the HTML results
        var text = StripHtml(html);

        // Truncate to a reasonable size for the LLM context
        const int maxChars = 3000;
        if (text.Length > maxChars)
            text = text[..maxChars] + "\n[...truncated]";

        return string.IsNullOrWhiteSpace(text)
            ? "No results found."
            : $"Search results for \"{query}\":\n{text}";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

static string StripHtml(string html)
{
    // Remove script/style blocks, then tags, then collapse whitespace
    var text = Regex.Replace(html, @"<(script|style)[^>]*>.*?</\1>", "", RegexOptions.Singleline);
    text = Regex.Replace(text, @"<[^>]+>", " ");
    text = WebUtility.HtmlDecode(text);
    text = Regex.Replace(text, @"\s+", " ").Trim();
    return text;
}

